            ('Проектируете ли вы закрытые переходы?', 'Да. Если траншею нельзя открыть — под дорогой, под трамвайными путями, под коммуникациями — делаем ППР на прокол или ГНБ: <a href="/ppr/naruzhnye-seti/gnb-i-prokol/">ППР на ГНБ и прокол</a>.'),
